#include <vector>
#include <omp.h>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        {
            max_threads = omp_get_num_threads();
        }
    }

    std::vector<double> blockSums(max_threads, 0.0);
    std::vector<double> blockOffsets(max_threads, 0.0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int T = omp_get_num_threads();

        const std::size_t start = (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(T);
        const std::size_t end   = (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(T);

        double running = 0.0;
        for (std::size_t i = start; i < end; ++i) {
            running += x[i];
            output[i] = running;
        }
        blockSums[tid] = running;

        #pragma omp barrier

        #pragma omp single
        {
            double accum = 0.0;
            for (int t = 0; t < T; ++t) {
                blockOffsets[t] = accum;
                accum += blockSums[t];
            }
        }

        #pragma omp barrier

        const double offset = blockOffsets[tid];
        if (offset != 0.0) {
            for (std::size_t i = start; i < end; ++i) {
                output[i] += offset;
            }
        }
    }
}
